{
  "title": "The Rescue of the Ember Heir",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A ruined royal city smolders under a bruised sky.",
      "visual_description": "Wide establishing shot of a collapsed skyline of broken spires, tattered banners, and smoke drifting over cracked streets.",
      "characters": ["Captain Wren"]
    },
    {
      "scene_number": 2,
      "caption": "The rescue party gathers at the city's outer wall.",
      "visual_description": "Four figures crouched behind a shattered statue, unrolling a map; the ruined castle looms in the distance.",
      "characters": ["Captain Wren", "Pip the Scout", "Mage Oris", "Lady Halden"]
    },
    {
      "scene_number": 3,
      "caption": "The mapmaker traces a safe path through the rubble.",
      "visual_description": "Close-up of a weathered parchment map with glowing ink lines, hands pointing toward a marked tower.",
      "characters": ["Lady Halden", "Captain Wren"]
    },
    {
      "scene_number": 4,
      "caption": "The castle gates stand cracked and tempting.",
      "visual_description": "Massive iron gates ajar, half-buried in vines, with carved lions split down the middle; a faint golden glow leaks through.",
      "characters": ["Pip the Scout", "Captain Wren"]
    },
    {
      "scene_number": 5,
      "caption": "An armored patrol marches along the broken avenue.",
      "visual_description": "A column of black-plated guards with spears, torchlight glinting on visors, passing a toppled fountain.",
      "characters": ["Captain Wren", "Pip the Scout", "Mage Oris", "Lady Halden"]
    },
    {
      "scene_number": 6,
      "caption": "Frightened townspeople whisper of a captured heir.",
      "visual_description": "Huddled civilians in a candlelit cellar, ragged clothes, wide eyes, pointing upward toward a cursed tower.",
      "characters": ["Captain Wren", "Mira the Baker", "Old Tomas"]
    },
    {
      "scene_number": 7,
      "caption": "Old Tomas dozes mid-sentence with crucial information.",
      "visual_description": "A round, bearded official slumped in a chair, snoring, a half-eaten loaf in his lap while others lean in eagerly.",
      "characters": ["Old Tomas", "Mira the Baker", "Captain Wren"]
    },
    {
      "scene_number": 8,
      "caption": "Rumors of a dragon circling the cursed tower.",
      "visual_description": "Silhouette of vast wings crossing a blood-red moon above a leaning black spire, seen from a broken window.",
      "characters": ["Pip the Scout", "Mage Oris"]
    },
    {
      "scene_number": 9,
      "caption": "Tattered royal banners mark the old processional road.",
      "visual_description": "Long crimson banners with faded gold sigils, half-burned, fluttering between leaning lamp posts on a cobbled street.",
      "characters": ["Captain Wren", "Lady Halden"]
    },
    {
      "scene_number": 10,
      "caption": "The party reaches a magic door sealed with runes.",
      "visual_description": "Tall stone door etched with concentric glowing sigils, pulsing blue, set into a moss-covered wall.",
      "characters": ["Mage Oris", "Captain Wren", "Pip the Scout", "Lady Halden"]
    },
    {
      "scene_number": 11,
      "caption": "Mage Oris coaxes the runes open with trembling hands.",
      "visual_description": "Close-up of glowing fingertips touching a sigil, light fanning across the door as cracks of bright energy spread.",
      "characters": ["Mage Oris"]
    },
    {
      "scene_number": 12,
      "caption": "Inside, a spiral stair winds up the cursed tower.",
      "visual_description": "Vertiginous interior shot looking up a crumbling spiral stair lit by floating candle flames.",
      "characters": ["Captain Wren", "Pip the Scout", "Mage Oris", "Lady Halden"]
    },
    {
      "scene_number": 13,
      "caption": "Pip scouts ahead and spots the captive heir.",
      "visual_description": "A small lithe figure peering through a barred slit; beyond, a young prisoner chained beside a flickering brazier.",
      "characters": ["Pip the Scout", "Prince Aldric"]
    },
    {
      "scene_number": 14,
      "caption": "The rescuers break the chains binding the heir.",
      "visual_description": "Captain Wren swinging a glowing sword down on iron shackles, sparks flying, the prince shielding his eyes.",
      "characters": ["Captain Wren", "Prince Aldric", "Mage Oris"]
    },
    {
      "scene_number": 15,
      "caption": "Alarm horns scream across the ruined city.",
      "visual_description": "View from a tower window: torches igniting across rooftops, patrols converging, banners snapping in sudden wind.",
      "characters": ["Pip the Scout", "Lady Halden", "Prince Aldric"]
    },
    {
      "scene_number": 16,
      "caption": "The party flees down through collapsing halls.",
      "visual_description": "Action shot of five figures sprinting through a corridor as stone blocks fall behind them, dust billowing.",
      "characters": ["Captain Wren", "Pip the Scout", "Mage Oris", "Lady Halden", "Prince Aldric"]
    },
    {
      "scene_number": 17,
      "caption": "A narrow stone bridge stretches over a roaring chasm.",
      "visual_description": "Crumbling arched bridge spanning a misty gorge, distant dragon silhouette wheeling overhead, dawn light breaking.",
      "characters": ["Captain Wren", "Pip the Scout", "Mage Oris", "Lady Halden", "Prince Aldric"]
    },
    {
      "scene_number": 18,
      "caption": "They cross to freedom as the bridge crumbles behind them.",
      "visual_description": "Final stones falling into the gorge as the five rescuers reach a green hillside lit by sunrise, the ruined city behind.",
      "characters": ["Captain Wren", "Pip the Scout", "Mage Oris", "Lady Halden", "Prince Aldric"]
    }
  ]
}

